import math

def solve_efficiently():
    solutions = []
    for a in range(1, 11):
        for b in range(a, 1008):
            fb = 2 * (a**3) * (b**3) - 2012 * a * (b**2) - 4024
            if fb == 0:
                solutions.append((a, b, b))
            elif fb < 0:
                c_crit_sq = (2012 * b) / (3 * (a**2))
                c_crit = math.sqrt(c_crit_sq)

                # If c_crit <= b, f(c) is increasing on [b, inf), so there's one root.
                # If c_crit > b, f(c) decreases then increases.
                # Since f(b) < 0 and f(c_crit) < f(b) < 0, there's no root in [b, c_crit].
                # There's exactly one root in (c_crit, inf).

                # In both cases, there is a root c > b.
                # Since a^3 c^3 - 2012abc + a^3 b^3 - 4024 = 0,
                # for large c, a^2 c^2 \approx 2012ab => c \approx sqrt(2012b/a^2).
                # So we can bound c by 2000 or even less.
                low = b + 1
                high = 2000
                while low <= high:
                    mid = (low + high) // 2
                    val = (a**3) * (mid**3) - (2012 * a * b) * mid + (a**3 * b**3 - 4024)
                    if val == 0:
                        solutions.append((a, b, mid))
                        break
                    elif val < 0:
                        low = mid + 1
                    else:
                        high = mid - 1
            elif fb > 0:
                c_crit_sq = (2012 * b) / (3 * (a**2))
                c_crit = math.sqrt(c_crit_sq)
                if c_crit > b:
                    f_c_crit = (a**3) * (c_crit**3) - (2012 * a * b) * c_crit + (a**3 * b**3 - 4024)
                    if f_c_crit < 0:
                        # Root in (b, c_crit]
                        l = b + 1
                        r = int(c_crit)
                        while l <= r:
                            m = (l + r) // 2
                            val = (a**3) * (m**3) - (2012 * a * b) * m + (a**3 * b**3 - 4024)
                            if val == 0:
                                solutions.append((a, b, m))
                                break
                            elif val > 0:
                                r = m - 1
                            else:
                                l = m + 1
                        # Root in (c_crit, infinity)
                        l = int(c_crit) + 1
                        r = 2000
                        while l <= r:
                            m = (l + r) // 2
                            val = (a**3) * (m**3) - (2012 * a * b) * m + (a**3 * b**3 - 4024)
                            if val == 0:
                                solutions.append((a, b, m))
                                break
                            elif val < 0:
                                l = m + 1
                            else:
                                r = m - 1
    return sorted(list(set(solutions)))

