def solve_S():
    solutions = []
    for S in range(2, 2013):
        num = S**3 - 4024
        den = 3*S + 2012
        if num % den == 0:
            P = num // den
            # Solve x^2 - Sx + P = 0
            # Discriminant D = S^2 - 4P
            D = S**2 - 4*P
            if D >= 0:
                import math
                sqrtD = int(math.isqrt(D))
                if sqrtD * sqrtD == D:
                    # Roots are (S +- sqrtD) / 2
                    if (S + sqrtD) % 2 == 0:
                        c = (S + sqrtD) // 2
                        b = (S - sqrtD) // 2
                        if b >= 1 and c >= b:
                            # Now check a^3(b^3+c^3) = 2012(abc+2)
                            # Since we only checked a=1 for this S-based method,
                            # let's generalize for all a.
                            for a in [1, 2, 4, 8]:
                                if a**3 * (b**3 + c**3) == 2012 * (a * b * c + 2):
                                    if b >= a:
                                        solutions.append((a, b, c))
    return solutions

